{
  "title": "Discussion about working and living abroad in Slovakia and Austria",
  "topics": [
    {
      "id": "living-abroad",
      "title": "Who lives in Slovakia or abroad",
      "claims": [
        {
          "text": "U1 asks if anyone lives in Bratislava, Slovakia, or has moved abroad",
          "evidence": [1]
        },
        {
          "text": "U2 mentions two acquaintances abroad: @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        },
        {
          "text": "U3 says they have at least two acquaintances in Austria",
          "evidence": [12]
        },
        {
          "text": "U3 notes one acquaintance recently arrived and another has been there for several years",
          "evidence": [13]
        },
        {
          "text": "U1 states they have been in Slovakia for almost a year and do not know the language",
          "evidence": [43]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Finding jobs abroad",
      "claims": [
        {
          "text": "U1 asks how to find a job abroad and whether it was difficult",
          "evidence": [16]
        },
        {
          "text": "U3 says it was hard but they managed within two months",
          "evidence": [17]
        },
        {
          "text": "U3 recommends searching on LinkedIn",
          "evidence": [18]
        },
        {
          "text": "U3 reports sending about 100 applications, receiving only 3 interview invitations",
          "evidence": [21]
        },
        {
          "text": "U3 says most vacancies require local language proficiency (95%)",
          "evidence": [26]
        },
        {
          "text": "U3 notes some cases accept candidates with little language skill",
          "evidence": [29]
        },
        {
          "text": "U3 says higher education rarely matters for hiring",
          "evidence": [32]
        },
        {
          "text": "U3 says they applied to any job without language requirement and to all tech stacks at first",
          "evidence": [36]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations for jobs",
      "claims": [
        {
          "text": "U1 asks which language is spoken in Austria (German)",
          "evidence": [14]
        },
        {
          "text": "U3 replies that communication with them is in English",
          "evidence": [15]
        },
        {
          "text": "U3 says most employers ask for B2 level German, sometimes B1, and certificates are not usually required",
          "evidence": [46]
        },
        {
          "text": "U3 mentions personal difficulty with language barrier in everyday life and feeling like a migrant if speaking English",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "salary-experience",
      "title": "Salary expectations and experience",
      "claims": [
        {
          "text": "U1 asks about approximate salary and whether U3 applied as a junior",
          "evidence": [34]
        },
        {
          "text": "U3 believes salaries in Europe are higher than in Ukraine but not many notice",
          "evidence": [35]
        },
        {
          "text": "U3 says they accepted a minimal salary despite higher offers because they needed work quickly",
          "evidence": [37]
        },
        {
          "text": "U3 mentions needing to find a job by 04.03, influencing salary acceptance",
          "evidence": [39]
        },
        {
          "text": "U1 notes that improving language skills could allow better job applications and confidence",
          "evidence": [42]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "U1 asks U3 personally how they feel about staying in Austria",
      "evidence": [58]
    }
  ]
}
